import { useEffect, useRef } from 'react';
import type { UsageActivityCategory, UsageEvent } from '../types/usageAnalytics';
import {
  categoryForRoute,
  contentTypeForRoute,
  eventTypeForRoute,
  recordUsageEvent
} from '../lib/usageAnalytics';

export function useUsagePageView(options: {
  route: string;
  label?: string;
  contentType?: UsageEvent['contentType'];
  contentId?: string;
  activityCategory?: UsageActivityCategory;
  metadata?: UsageEvent['metadata'];
}): void {
  const startRef = useRef<number | null>(null);
  const routeRef = useRef<string | null>(null);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const now = Date.now();
    startRef.current = now;
    routeRef.current = options.route;

    recordUsageEvent({
      eventType: eventTypeForRoute(options.route),
      route: options.route,
      label: options.label,
      contentType: options.contentType ?? contentTypeForRoute(options.route),
      contentId: options.contentId,
      activityCategory: options.activityCategory ?? categoryForRoute(options.route),
      metadata: options.metadata
    });

    return () => {
      const startedAt = startRef.current;
      const trackedRoute = routeRef.current;
      if (!startedAt || !trackedRoute) {
        return;
      }

      const durationSeconds = Math.round((Date.now() - startedAt) / 1000);
      if (durationSeconds < 2) {
        return;
      }

      recordUsageEvent({
        eventType: 'section_view',
        route: trackedRoute,
        label: options.label,
        contentType: options.contentType ?? contentTypeForRoute(trackedRoute),
        contentId: options.contentId,
        activityCategory: options.activityCategory ?? categoryForRoute(trackedRoute),
        durationSeconds,
        completed: true,
        metadata: options.metadata
      });
    };
  }, [
    options.route,
    options.label,
    options.contentType,
    options.contentId,
    options.activityCategory,
    options.metadata?.domain,
    options.metadata?.level,
    options.metadata?.source,
    options.metadata?.weakTopic
  ]);
}

export function trackUsageInteraction(event: Omit<UsageEvent, 'id' | 'timestamp'>): void {
  recordUsageEvent(event);
}
