            reflection, or portfolio sharing.
          </p>
        </div>
      </section>

      <PrivacyReminder />

      <div className="grid gap-6 lg:grid-cols-[1fr_360px]">
        <EvidencePackPreview markdown={markdown} />

        <section className="rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
