              disabled={!markdown}
              className="rounded-full bg-slate-900 px-4 py-2 text-sm text-white disabled:opacity-50"
            >
              {copied ? 'Copied!' : 'Copy Markdown'}
            </button>
          </div>
        </section>
      </div>
    </div>
  );
}

